BEGIN TRANSACTION READ ONLY; SET LOCAL statement_timeout='15000ms'; SELECT jsonb_build_object('policies',(SELECT jsonb_agg(jsonb_build_object('schema',schemaname,'table',tablename,'name',policyname,'roles',roles,'command',cmd,'usingAlwaysTrue',coalesce(qual IN ('true','(true)'),false),'withCheckAlwaysTrue',coalesce(with_check IN ('true','(true)'),false),'usingContainsAuthUidText',coalesce(qual ILIKE '%auth.uid%',false))) FROM pg_policies WHERE schemaname='gamification' AND tablename IN ('xp_ledger','login_rewards')),'access',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'relation',c.relname,'role',r.name,'schemaUsage',has_schema_privilege(r.name,n.oid,'USAGE'),'select',has_table_privilege(r.name,c.oid,'SELECT'),'insert',has_table_privilege(r.name,c.oid,'INSERT'),'update',has_table_privilege(r.name,c.oid,'UPDATE'),'delete',has_table_privilege(r.name,c.oid,'DELETE'),'relkind',c.relkind,'securityInvoker',coalesce(c.reloptions @> ARRAY['security_invoker=true'],false))) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN (VALUES ('anon'),('authenticated')) r(name) WHERE (n.nspname='gamification' AND c.relname IN ('xp_ledger','login_rewards')) OR (n.nspname='public' AND c.relname IN ('gamification_xp_ledger','gamification_login_rewards'))),'pg_net',(SELECT jsonb_build_object('schema',n.nspname,'version',e.extversion,'relocatable',e.extrelocatable) FROM pg_extension e JOIN pg_namespace n ON n.oid=e.extnamespace WHERE e.extname='pg_net')) AS result; ROLLBACK;
